# temperature
# problem:
# write a function convert_trap() that takes a temperature and a scale ("C" for celsius, "F" for fahrenheit)




def convert_temp(temp, scale):
  if scale == "C":
    return (temp * 9 / 5) + 32
  elif scale == "F":
    return (temp - 32) * 5 / 9
  else:
    return "Use 'C' or 'F' for the scale."

print(convert_temp(100, "C"))
print(convert_temp(100, "F"))
print(convert_temp(100, "S"))

