# problem:
# create a function withdrawal(balance, amount)
# that checks if the amount is less than or equal to the balance
# if yes, subtract it and return the return the new balance
# otherwise return "insufficient"

def withdrawal(balance, amount):
    if amount <= balance:
        return balance - amount
    else:
        return "insufficient"
print(withdrawal(100, 3))